DASHBOARD_HTML = r"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <title>T3-2026 GA1 API Hub</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root{color-scheme:dark;--bg:#080d19;--panel:#111a2b;--panel2:#162238;--line:#263650;--text:#ecf2ff;--muted:#9aabc4;--blue:#7ab8ff;--mint:#71e0c1;--warn:#ffc36e;--red:#ff8585}
    *{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 15% -5%,#19335a 0,transparent 45%),var(--bg);color:var(--text);font:15px Manrope,system-ui,sans-serif;line-height:1.55}
    main{max-width:1120px;margin:auto;padding:46px 22px 72px}.hero{padding:12px 0 30px}.eyebrow{text-transform:uppercase;letter-spacing:.16em;color:var(--mint);font-size:11px;font-weight:800}.hero h1{font-size:clamp(32px,6vw,56px);letter-spacing:-.05em;line-height:1.08;margin:12px 0}.hero p{color:var(--muted);max-width:760px}
    .panel,.card{border:1px solid var(--line);background:linear-gradient(145deg,#121d30,#0f1728);border-radius:17px;padding:22px;box-shadow:0 18px 50px #0002}.panel{margin:18px 0 30px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,315px),1fr));gap:15px}.card{display:flex;flex-direction:column;gap:12px}.card h2{font-size:19px;margin:2px 0}.tag{color:var(--mint);font:11px 'DM Mono',monospace;text-transform:uppercase;letter-spacing:.08em}.muted,.hint{color:var(--muted);font-size:13px}.row{display:flex;gap:9px;flex-wrap:wrap}input,textarea{width:100%;border:1px solid #314563;background:#0a1221;color:var(--text);padding:11px 12px;border-radius:9px;font:13px 'DM Mono',monospace}label{font-weight:700;font-size:13px}.field{display:grid;gap:6px}.btn{border:1px solid #35577f;border-radius:9px;background:#1c3c63;color:#eaf4ff;padding:10px 14px;font-weight:800;cursor:pointer}.btn:hover{background:#275484}.secondary{background:#18243a;border-color:#34445e}.result{min-height:48px;max-height:300px;overflow:auto;white-space:pre-wrap;word-break:break-word;padding:12px;border:1px solid var(--line);border-radius:9px;background:#070c15;color:#c5f5e6;font:12px 'DM Mono',monospace}.url{font:11px 'DM Mono',monospace;color:#b9d5ff;overflow-wrap:anywhere;background:#0a1221;padding:10px;border-radius:8px}.ok{color:var(--mint)}.error{color:var(--red)}.warn{color:var(--warn)}
    @media(max-width:560px){main{padding:28px 14px 48px}.panel,.card{padding:17px}}
  </style>
</head>
<body><main>
  <header class="hero"><div class="eyebrow">T3 · 2026 · API workspace</div><h1>GA1 service bench</h1><p>Live config, Ledger, and MCP APIs, plus a stateless Q13 decoding helper. Q13 still requires your own signed terminal recording; its helper URL is not an exam submission.</p></header>
  <section class="panel">
    <div class="tag">Student setup</div><h2>Email and exam session</h2>
    <div class="grid">
      <div class="field"><label for="email">Exam email</label><input id="email" type="email" placeholder="student@ds.study.iitm.ac.in"></div>
      <div class="field"><label for="question-data-url">Your signed Ledger questionData URL</label><textarea id="question-data-url" rows="4" autocomplete="off" placeholder="Paste the complete questionData URL from your active exam session"></textarea></div>
    </div>
    <p class="hint">Paste the complete signed URL shown in your exam, including email, quizSign, questionId, and path. The API validates it against the email and Ledger question, stores only the signature server-side, and never returns it in generated routes. Treat the URL as a secret; discovery displays schema metadata, not ledger rows.</p>
    <div class="row"><button class="btn" onclick="setup()">Save setup and generate URLs</button><span id="setup-state" class="hint"></span></div>
  </section>
  <section class="grid">
    <article class="card"><div class="tag">Q13 · Decode it in the terminal</div><h2>ROT13 / hex / reversal helper</h2><p class="muted">No Ledger setup needed. Paste only the current ciphertext, not your signed URL or credentials. Tries all six orders and reports readable candidates with shell pipelines. Fetch and decode inside your own termlog recording; submit the archive URL.</p><div class="field"><label for="q13-ciphertext">Ciphertext</label><textarea id="q13-ciphertext" rows="4" maxlength="16384" autocomplete="off" spellcheck="false"></textarea></div><button class="btn" onclick="testQ13()">Find decode candidates</button><pre class="result" id="res-q13">Ready without onboarding. Ambiguous results require inspection.</pre></article>
    <article class="card"><div class="tag">Question · Resolve 12-Factor Config Precedence</div><h2>Effective config</h2><p class="muted">Checks fresh repeated <code>set=key=value</code> overrides, type coercion, the worker alias, and secret masking.</p><div class="url" id="url-config">Save setup to generate the tenant route.</div><div class="row"><button class="btn" onclick="testConfig()">Run override test</button><button class="btn secondary" onclick="copy('url-config')">Copy URL</button></div><pre class="result" id="res-config">Ready when setup is saved.</pre></article>
    <article class="card"><div class="tag">Question · The Ledger Agent</div><h2>Student data discovery and answer API</h2><p class="muted">Fetches your signed ledger root, follows advertised resources, then accepts natural-language questions as <code>{"question":"…"}</code>.</p><div class="url" id="url-ledger">Save setup to generate the tenant route.</div><div class="row"><button class="btn secondary" onclick="discover()">Discover ledger</button><button class="btn" onclick="testLedger()">Try sample question</button><button class="btn secondary" onclick="copy('url-ledger')">Copy URL</button></div><textarea id="ledger-question" rows="2">What was the total revenue in USD from the North region in March 2026?</textarea><pre class="result" id="res-ledger">Ledger discovery requires the active exam quizSign.</pre></article>
    <article class="card"><div class="tag">Question · Build a Live MCP Server</div><h2>MCP protocol test</h2><p class="muted">Runs initialize, initialized notification, tools/list, and a tools/call with a fresh challenge header.</p><div class="url" id="url-mcp">Save setup to generate the tenant route.</div><div class="row"><button class="btn" onclick="testMcp()">Run MCP handshake and challenge</button><button class="btn secondary" onclick="copy('url-mcp')">Copy URL</button></div><pre class="result" id="res-mcp">Ready when setup is saved.</pre></article>
  </section>
  <p class="hint" style="margin-top:20px">This bench exercises the hub routes. The exam grader performs its own live calls to the submitted public endpoint.</p>
</main>
<script>
const byId=id=>document.getElementById(id), root=()=>location.pathname.replace(/\/$/,'');let routes=null;
function show(id,value,error=false){const el=byId(id);el.textContent=typeof value==='string'?value:JSON.stringify(value,null,2);el.className='result'+(error?' error':'')}
function encEmail(){return encodeURIComponent(byId('email').value.trim().toLowerCase())}
async function setup(){const email=byId('email').value.trim().toLowerCase();const question_data_url=byId('question-data-url').value.trim();if(!email){byId('setup-state').textContent='Enter an email first.';return}if(!question_data_url){byId('setup-state').textContent='Paste your complete signed Ledger questionData URL.';return}try{const r=await fetch(`${root()}/onboard`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,question_data_url})});const data=await r.json();if(!r.ok)throw Error(JSON.stringify(data));routes=data.routes;for(const [key,id] of [['effective_config','url-config'],['ledger_answer','url-ledger'],['mcp','url-mcp']])byId(id).textContent=routes[key];byId('setup-state').textContent=`Routes ready for ${email}`;byId('setup-state').className='hint ok';byId('question-data-url').value=''}catch(e){byId('setup-state').textContent=e.message;byId('setup-state').className='hint error'}}
async function copy(id){await navigator.clipboard.writeText(byId(id).textContent)}
async function testQ13(){try{const r=await fetch(`${root()}/q13/decode`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ciphertext:byId('q13-ciphertext').value})});show('res-q13',{http:r.status,response:await r.json()},!r.ok)}catch(e){show('res-q13',e.message,true)}}
async function testConfig(){if(!routes){show('res-config','Save setup first.',true);return}const params=new URLSearchParams();params.append('set','port=8765');params.append('set','debug=yes');params.append('set','num_workers=4');const r=await fetch(`${routes.effective_config}?${params}`);const data=await r.json();show('res-config',{http:r.status,response:data});if(!r.ok||data.port!==8765||data.debug!==true||data.workers!==4||data.api_key!=='****')show('res-config',{http:r.status,response:data,expected:'port 8765, debug true, workers 4, masked api_key'},true)}
async function discover(){if(!routes){show('res-ledger','Save setup first.',true);return}try{const r=await fetch(routes.ledger_discover);show('res-ledger',{http:r.status,response:await r.json()},!r.ok)}catch(e){show('res-ledger',e.message,true)}}
async function testLedger(){if(!routes){show('res-ledger','Save setup first.',true);return}try{const r=await fetch(routes.ledger_answer,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:byId('ledger-question').value})});show('res-ledger',{http:r.status,response:await r.json()},!r.ok)}catch(e){show('res-ledger',e.message,true)}}
async function testMcp(){if(!routes){show('res-mcp','Save setup first.',true);return}try{const url=routes.mcp;const post=(body,headers={})=>fetch(url,{method:'POST',headers:{'Content-Type':'application/json',...headers},body:JSON.stringify(body)});let init=await (await post({jsonrpc:'2.0',id:1,method:'initialize',params:{protocolVersion:'2025-03-26',capabilities:{},clientInfo:{name:'ga1-dashboard-bench',version:'1'}}})).json();await post({jsonrpc:'2.0',method:'notifications/initialized'});let listed=await (await post({jsonrpc:'2.0',id:2,method:'tools/list'})).json();const challenge=crypto.randomUUID().replaceAll('-','').slice(0,32);let called=await (await post({jsonrpc:'2.0',id:3,method:'tools/call',params:{name:'solve_challenge',arguments:{}}},{'X-Exam-Challenge':challenge,'X-Exam-Timestamp':String(Date.now())})).json();const email=byId('email').value.trim().toLowerCase();const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(`${challenge}:${email}`));const expected=Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('').slice(0,16);const actual=called.result?.content?.[0]?.text;const pass=init.result?.capabilities?.tools!==undefined&&listed.result?.tools?.length===1&&listed.result.tools[0].name==='solve_challenge'&&actual===expected;show('res-mcp',{status:pass?'PASS':'FAIL',expected,actual,initialize:init,tools:listed,challenge,call:called},!pass)}catch(e){show('res-mcp',e.message,true)}}
</script></body></html>"""
